-- =====================================================================
-- V14 — M6 Finance: Sales Invoice + Purchase Invoice + Payment Receipt
--       + Payment Made + AR/AP aging views.
-- =====================================================================

CREATE TABLE IF NOT EXISTS m6_sales_invoice (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 1,
  invoice_no VARCHAR(32) NOT NULL,
  invoice_date DATE NOT NULL,
  customer_name VARCHAR(256) NOT NULL,
  gstin VARCHAR(16) NULL,
  linked_so_id BIGINT NULL,
  linked_dispatch_id BIGINT NULL,
  subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,
  tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  balance DECIMAL(14,2) NOT NULL DEFAULT 0,
  due_date DATE NULL,
  irn VARCHAR(64) NULL,
  irn_qr TEXT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  current_step VARCHAR(64) NULL,
  workflow_instance_id BIGINT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_si_no (tenant_id, invoice_no),
  KEY idx_si_status (tenant_id, status, due_date)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS m6_purchase_invoice (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 1,
  vendor_invoice_no VARCHAR(32) NOT NULL,
  invoice_date DATE NOT NULL,
  vendor_name VARCHAR(256) NOT NULL,
  vendor_gstin VARCHAR(16) NULL,
  linked_po_id BIGINT NULL,
  linked_grn_id BIGINT NULL,
  subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,
  tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  balance DECIMAL(14,2) NOT NULL DEFAULT 0,
  due_date DATE NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  current_step VARCHAR(64) NULL,
  workflow_instance_id BIGINT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_pi_no (tenant_id, vendor_invoice_no),
  KEY idx_pi_status (tenant_id, status, due_date)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS m6_payment (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 1,
  payment_no VARCHAR(32) NOT NULL,
  payment_date DATE NOT NULL,
  direction VARCHAR(8) NOT NULL,
  counterparty VARCHAR(256) NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  mode VARCHAR(16) NOT NULL,
  reference_no VARCHAR(64) NULL,
  applied_invoice_no VARCHAR(32) NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'POSTED',
  notes TEXT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_pay_no (tenant_id, payment_no),
  KEY idx_pay_direction (tenant_id, direction, payment_date)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4;

