INSERT IGNORE INTO workflow_definition (tenant_id, code, version, status, body_json) VALUES
(1,'M6.SalesInvoice',1,'PUBLISHED','{"code":"M6.SalesInvoice","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT","assignedRole":"Dispatch"},{"code":"FINALIZED","assignedRole":"Manager"},{"code":"E_INVOICED","assignedRole":"Dispatch"},{"code":"SENT","assignedRole":"Dispatch"},{"code":"PARTIAL","assignedRole":"Dispatch"},{"code":"PAID","terminal":true},{"code":"CANCELLED","terminal":true}],"transitions":[{"from":"DRAFT","to":"FINALIZED","trigger":"page.submitted","pageCode":"pico:si-finalize"},{"from":"FINALIZED","to":"E_INVOICED","trigger":"page.submitted","pageCode":"pico:si-einvoice"},{"from":"E_INVOICED","to":"SENT","trigger":"page.submitted","pageCode":"pico:si-send"},{"from":"SENT","to":"PARTIAL","trigger":"page.submitted","pageCode":"pico:si-payment","guard":"#submitted[''mode''] == ''PARTIAL''"},{"from":"SENT","to":"PAID","trigger":"page.submitted","pageCode":"pico:si-payment","guard":"#submitted[''mode''] == ''FULL''"},{"from":"PARTIAL","to":"PAID","trigger":"page.submitted","pageCode":"pico:si-payment","guard":"#submitted[''mode''] == ''FULL''"}]}'),
(1,'M6.PurchaseInvoice',1,'PUBLISHED','{"code":"M6.PurchaseInvoice","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT","assignedRole":"Dispatch"},{"code":"MATCHED","assignedRole":"Manager"},{"code":"APPROVED","assignedRole":"Dispatch"},{"code":"PARTIAL","assignedRole":"Dispatch"},{"code":"PAID","terminal":true},{"code":"DISPUTED","terminal":true}],"transitions":[{"from":"DRAFT","to":"MATCHED","trigger":"page.submitted","pageCode":"pico:pi-3way-match"},{"from":"MATCHED","to":"APPROVED","trigger":"page.submitted","pageCode":"pico:pi-approve","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"MATCHED","to":"DISPUTED","trigger":"page.submitted","pageCode":"pico:pi-approve","guard":"#submitted[''status''] == ''DISPUTED''"},{"from":"APPROVED","to":"PARTIAL","trigger":"page.submitted","pageCode":"pico:pi-payment","guard":"#submitted[''mode''] == ''PARTIAL''"},{"from":"APPROVED","to":"PAID","trigger":"page.submitted","pageCode":"pico:pi-payment","guard":"#submitted[''mode''] == ''FULL''"},{"from":"PARTIAL","to":"PAID","trigger":"page.submitted","pageCode":"pico:pi-payment","guard":"#submitted[''mode''] == ''FULL''"}]}');

