INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"New Purchase Invoice","fields":[{"kind":"FormField","type":"text","name":"vendorInvoiceNo","label":"Vendor Invoice #"},{"kind":"FormField","type":"text","name":"vendorName","label":"Vendor"},{"kind":"FormField","type":"text","name":"vendorGstin","label":"Vendor GSTIN"},{"kind":"FormField","type":"text","name":"linkedPoNumber","label":"Linked PO #"},{"kind":"FormField","type":"text","name":"linkedGrnNumber","label":"Linked GRN #"},{"kind":"FormField","type":"number","name":"subtotal","label":"Subtotal"},{"kind":"FormField","type":"number","name":"taxAmount","label":"Tax"},{"kind":"FormField","type":"text","name":"dueDate","label":"Due Date"},{"kind":"WorkflowActionButton","label":"Save Draft","action":"save","variant":"primary"}]}]}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:pi-create' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"3-Way Match","fields":[{"kind":"FormField","type":"text","name":"poQty","label":"PO Qty"},{"kind":"FormField","type":"text","name":"grnQty","label":"GRN Qty"},{"kind":"FormField","type":"text","name":"invoiceQty","label":"Invoice Qty"},{"kind":"FormField","type":"text","name":"varianceQty","label":"Variance"},{"kind":"FormField","type":"text","name":"varianceAmount","label":"Variance Amount"},{"kind":"WorkflowActionButton","label":"Submit Match","action":"workflow.transition","variant":"primary"}]}]}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:pi-3way-match' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Manager Approve / Dispute","fields":[{"kind":"FormField","type":"text","name":"reason","label":"Reason"},{"kind":"FormField","type":"select","name":"status","label":"Decision","options":[{"label":"APPROVED","value":"APPROVED"},{"label":"DISPUTED","value":"DISPUTED"}]},{"kind":"WorkflowActionButton","label":"Submit","action":"workflow.transition","variant":"primary"}]}]}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:pi-approve' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Make Payment to Vendor","fields":[{"kind":"FormField","type":"text","name":"paymentNo","label":"Payment #"},{"kind":"FormField","type":"number","name":"amount","label":"Amount"},{"kind":"FormField","type":"select","name":"paymentMode","label":"Mode","options":[{"label":"NEFT","value":"NEFT"},{"label":"RTGS","value":"RTGS"},{"label":"CHEQUE","value":"CHEQUE"},{"label":"UPI","value":"UPI"}]},{"kind":"FormField","type":"text","name":"referenceNo","label":"Bank Reference"},{"kind":"FormField","type":"select","name":"mode","label":"Settles invoice as","options":[{"label":"FULL","value":"FULL"},{"label":"PARTIAL","value":"PARTIAL"}]},{"kind":"WorkflowActionButton","label":"Post Payment","action":"workflow.transition","variant":"primary"}]}]}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:pi-payment' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"list","schemaVersion":2,"dataSource":{"type":"entity","entity":"Payment","filter":{"and":[{"field":"tenant_id","op":"eq","value":1}]},"select":["id","payment_no","payment_date","direction","counterparty","amount","mode","reference_no","applied_invoice_no"]},"columns":[{"field":"payment_no","label":"#","sticky":"left","sortable":true},{"field":"payment_date","label":"Date","render":"date"},{"field":"direction","label":"Dir","render":"badge","colorMap":{"RECEIPT":"green","PAYMENT":"amber"}},{"field":"counterparty","label":"Counterparty"},{"field":"amount","label":"Amount","render":"number","align":"right"},{"field":"mode","label":"Mode","render":"badge","colorMap":{"NEFT":"blue","RTGS":"blue","CHEQUE":"purple","CASH":"amber","UPI":"green"}},{"field":"reference_no","label":"Ref"},{"field":"applied_invoice_no","label":"Invoice"}],"filters":[{"field":"direction","label":"Direction","type":"multi-select","optionsSource":{"type":"static","options":["RECEIPT","PAYMENT"]}},{"field":"mode","label":"Mode","type":"multi-select","optionsSource":{"type":"static","options":["NEFT","RTGS","CHEQUE","CASH","UPI"]}}],"sort":{"default":[{"field":"payment_date","dir":"desc"}]},"pagination":{"kind":"server","pageSize":50},"header":{"title":"Payments"}}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:payment-list' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"schemaVersion":2,"layout":{"type":"Grid","props":{"gap":16,"style":{"padding":16,"gridTemplateColumns":"repeat(auto-fit, minmax(200px, 1fr))"}},"children":[{"type":"KPI","props":{"label":"Total Outstanding (INR)","intervalMs":60000,"dataSource":{"type":"entity","entity":"SalesInvoice","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"balance","op":"gt","value":0}]}}}},{"type":"KPI","props":{"label":"Invoices Overdue","intervalMs":60000,"dataSource":{"type":"entity","entity":"SalesInvoice","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"status","op":"in","value":["SENT","PARTIAL","UNPAID"]}]}}}},{"type":"KPI","props":{"label":"Paid Last 30d","intervalMs":60000,"dataSource":{"type":"entity","entity":"Payment","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"direction","op":"eq","value":"RECEIPT"}]}}}}]}}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:rpt-ar-aging' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"schemaVersion":2,"layout":{"type":"Grid","props":{"gap":16,"style":{"padding":16,"gridTemplateColumns":"repeat(auto-fit, minmax(200px, 1fr))"}},"children":[{"type":"KPI","props":{"label":"Total Payable (INR)","intervalMs":60000,"dataSource":{"type":"entity","entity":"PurchaseInvoice","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"balance","op":"gt","value":0}]}}}},{"type":"KPI","props":{"label":"Vendor Bills Overdue","intervalMs":60000,"dataSource":{"type":"entity","entity":"PurchaseInvoice","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"status","op":"in","value":["APPROVED","PARTIAL","UNPAID"]}]}}}},{"type":"KPI","props":{"label":"Paid Out Last 30d","intervalMs":60000,"dataSource":{"type":"entity","entity":"Payment","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"direction","op":"eq","value":"PAYMENT"}]}}}}]}}', 'V14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:rpt-ap-aging' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:si-list','pico:si-create','pico:si-finalize','pico:si-einvoice','pico:si-send','pico:si-payment','pico:pi-list','pico:pi-create','pico:pi-3way-match','pico:pi-approve','pico:pi-payment','pico:payment-list','pico:rpt-ar-aging','pico:rpt-ap-aging') AND current_version_id IS NULL;
